const HOT_HANDLED = 'Hot Handled';
const SETTINGS_HEADERS = [
  'Sender Name', 'Sender Title', 'Company Legal Name', 'Company Address',
  'Opt-out TR', 'Opt-out EN', 'Nil Email', 'Sheet URL',
